S = "Hakeem Force Academy"
QS = [
(S, "How many Muslims were martyred in the Battle of Uhud (Ghazwa Ohad) according to the most commonly accepted account?", ["70", "50", "85", "100"], 0, "In the Battle of Uhud in 3 Hijri about 70 Muslims were martyred, most of them from the Ansar. Hazrat Hamza (RA) was among them.", "Some sources give slightly different numbers, so sources differ, but 70 is the figure most Pakistani textbooks use.", [125]),
(S, "On which date was Hazrat Ali (RA) martyred?", ["21 Ramzan 40 Hijri", "17 Ramzan 40 Hijri", "10 Muharram 61 Hijri", "21 Ramzan 35 Hijri"], 0, "Hazrat Ali (RA) was attacked by Abdur Rahman bin Muljam while praying in Kufa and was martyred on 21 Ramzan 40 Hijri.", "This date matches about 30 January 661 AD.", [328]),
(S, "Where is Masjid Khaif located?", ["Mina", "Madinah", "Taif", "Jeddah"], 0, "Masjid Khaif is a historic mosque in the valley of Mina near Makkah. Many prophets are said to have prayed there.", "Mina is where pilgrims stay and perform the stoning of the Jamarat during Hajj.", [356]),
(S, "What is the full form of IRDA?", ["Insurance Regulatory and Development Authority", "International Revenue and Duty Authority", "Indian Rural Development Agency", "Insurance Reserve and Debt Authority"], 0, "IRDA stands for Insurance Regulatory and Development Authority, the body that regulates the insurance sector in India.", "It was set up under an Act of the Indian Parliament in 1999.", [232]),
(S, "What is the meaning of the word Islam?", ["Submission and peace", "War", "Wealth", "Prayer only"], 0, "The word Islam comes from the Arabic root s-l-m, meaning submission to Allah and peace.", "A person who follows Islam is called a Muslim, meaning one who submits.", [233]),
(S, "What does the word Miraath mean?", ["Inheritance", "Charity", "Trade", "Loan"], 0, "Miraath is an Arabic word meaning inheritance, the property left by a dead person.", "The rules of inheritance are given in Surah An-Nisa of the Quran.", [235]),
(S, "What is the meaning of the name Muhammad?", ["The praised one", "The truthful", "The trustworthy", "The guide"], 0, "The name Muhammad comes from the root h-m-d, meaning praise. Muhammad means one who is highly praised.", "The Prophet (SAW) was also called Al-Amin (the trustworthy) before prophethood.", [236]),
(S, "Which two Surahs of the Quran are called Muawwidhatain (Moaztain)?", ["Surah Al-Falaq and Surah An-Nas", "Surah Al-Ikhlas and Surah Al-Falaq", "Surah Al-Fatiha and Surah Al-Ikhlas", "Surah Al-Kafirun and Surah An-Nas"], 0, "Surah Al-Falaq (113) and Surah An-Nas (114) teach us to seek refuge with Allah, so they are called Muawwidhatain.", "They are the last two surahs of the Quran.", [394]),
(S, "In which year was the Badshahi Mosque of Lahore built?", ["1673", "1627", "1556", "1700"], 0, "The Badshahi Mosque was built by Mughal emperor Aurangzeb Alamgir and completed in 1673.", "For centuries it was the largest mosque in the world by capacity, and it stands opposite Lahore Fort.", [22]),
(S, "In which area of Pakistan is the largest coal reserve found?", ["Thar in Sindh", "Hazara in KPK", "Quetta in Balochistan", "Salt Range in Punjab"], 0, "The Thar coalfield in Sindh holds about 175 billion tonnes of lignite coal, the largest reserve in Pakistan.", "Thar coal is now used to generate electricity near Islamkot.", [19]),
(S, "What is the highest mountain of the Balochistan plateau?", ["Zarghun Ghar", "Takatu", "Koh-e-Sulaiman", "Chiltan"], 0, "Zarghun Ghar near Quetta is the highest peak in Balochistan at about 3,578 metres.", "Takatu mountain overlooks Quetta city and is a well known nearby peak.", [274]),
(S, "Where is Mount Whitney located?", ["Sierra Nevada, California, USA", "Appalachian Mountains, USA", "Rocky Mountains, Canada", "Alps, Switzerland"], 0, "Mount Whitney, about 4,421 metres, is in the Sierra Nevada range in California.", "It is the highest peak in the contiguous United States.", [385]),
(S, "Who appointed Hazrat Muaz bin Jabal (RA) as governor of Yemen?", ["The Holy Prophet Muhammad (SAW)", "Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)"], 0, "The Holy Prophet (SAW) sent Hazrat Muaz bin Jabal (RA) to Yemen as governor and teacher in 10 Hijri.", "He is known as the most knowledgeable Companion about halal and haram.", [452]),
(S, "Which of the following was NOT a daughter of the Holy Prophet (SAW)?", ["Aisha", "Zainab", "Ruqayyah", "Umm Kulthum"], 0, "The four daughters of the Prophet (SAW) were Zainab, Ruqayyah, Umm Kulthum and Fatima (RA). Aisha (RA) was his wife.", "Hazrat Fatima (RA) was the youngest and married Hazrat Ali (RA).", [225]),
(S, "What were the old names of India?", ["Hindustan and Bharat", "Gandhara and Sindh", "Persia and Turan", "Ceylon and Burma"], 0, "India has been called Hindustan, Bharat and Bharatvarsha since ancient times.", "The name India comes from the River Indus (Sindhu).", [228, 297]),
(S, "Hub Dam and Hub Lake are near which city?", ["Karachi", "Lahore", "Quetta", "Hyderabad"], 0, "Hub Dam is on the Hub River on the border of Sindh and Balochistan, and it supplies water to Karachi.", "The Hub River forms part of the border between Sindh and Balochistan.", [141]),
(S, "If nP2 = 20, what is the value of n?", ["5", "4", "10", "20"], 0, "nP2 = n(n-1) = 20. Since 5 x 4 = 20, n = 5.", "nPr = n! divided by (n-r)!.", [146]),
(S, "On which date did Pakistan become a member of the United Nations?", ["30 September 1947", "14 August 1947", "24 October 1945", "23 March 1948"], 0, "Pakistan was admitted to the UN on 30 September 1947 as its 56th member.", "Afghanistan was the only country that voted against Pakistan's admission.", [187]),
(S, "On which date was the League of Nations founded?", ["10 January 1920", "28 June 1919", "24 October 1945", "1 September 1939"], 0, "The League of Nations came into being on 10 January 1920 after the Treaty of Versailles, with its headquarters in Geneva.", "It was replaced by the United Nations in 1945.", [193]),
(S, "On which date was the Objectives Resolution presented in the Constituent Assembly of Pakistan?", ["7 March 1949", "12 March 1949", "14 August 1947", "23 March 1956"], 0, "Prime Minister Liaquat Ali Khan presented the Objectives Resolution on 7 March 1949.", "It was passed on 12 March 1949.", [194, 195]),
(S, "Pakistan opposed the entry of India into which group?", ["Nuclear Suppliers Group (NSG)", "SAARC", "Commonwealth", "G20"], 0, "India applied for NSG membership in 2016 and Pakistan opposed it, saying it should be treated equally with India.", "The NSG is a group of countries that controls exports of nuclear material.", [25]),
(S, "Pakistan became a full member of which organization in 2017?", ["Shanghai Cooperation Organization (SCO)", "SAARC", "OPEC", "NATO"], 0, "Pakistan and India became full members of the SCO at the Astana summit in June 2017.", "Pakistan had been an observer in the SCO since 2005.", [78]),
(S, "What happened in the First Battle of Panipat?", ["Babur defeated Ibrahim Lodhi on 21 April 1526", "Akbar defeated Hemu in 1556", "Ahmad Shah Abdali defeated the Marathas in 1761", "Sher Shah defeated Humayun in 1540"], 0, "On 21 April 1526 Babur defeated Ibrahim Lodhi at Panipat, which began Mughal rule in India.", "Babur used cannons and matchlocks, which gave him the victory.", [24, 217]),
(S, "Who defeated Hemu in the Second Battle of Panipat (5 November 1556)?", ["Akbar's army", "Babur", "Ahmad Shah Abdali", "Humayun"], 0, "The army of the young Akbar, led by Bairam Khan, defeated Hemu (Hemachandra Vikramaditya) at Panipat in 1556.", "Akbar was only 13 years old at the time.", [219]),
(S, "Whom did Ahmad Shah Abdali defeat in the Third Battle of Panipat (14 January 1761)?", ["The Marathas", "The Mughals", "The Sikhs", "The British"], 0, "Ahmad Shah Abdali (Durrani) defeated the Marathas led by Sadashiv Rao Bhau at Panipat in 1761.", "The defeat greatly weakened Maratha power in north India.", [221]),
(S, "In which mountain range is Zardak Peak located?", ["Kirthar Range, Sindh", "Sulaiman Range", "Karakoram", "Salt Range"], 0, "Zardak Peak (about 2,260 metres) is the highest point of the Kirthar Range on the Sindh and Balochistan border.", "The Kirthar Range runs north to south west of the Indus.", [387]),
(S, "What is the Pentagon?", ["Headquarters of the US Department of Defense", "The US parliament building", "The residence of the US President", "The headquarters of NATO"], 0, "The Pentagon in Arlington, Virginia is the headquarters of the United States Department of Defense.", "It is named after its five-sided shape.", [50]),
(S, "Where is the permanent secretariat of SAARC?", ["Kathmandu, Nepal", "Dhaka, Bangladesh", "Islamabad, Pakistan", "New Delhi, India"], 0, "The SAARC Secretariat was set up in Kathmandu in 1987.", "SAARC was founded in Dhaka in 1985.", [377]),
(S, "Which word is closest in meaning to Prescribe?", ["Dictate", "Forget", "Refuse", "Delay"], 0, "To prescribe means to order or lay down a rule, which is close to dictate.", "A doctor prescribes medicine by ordering it for a patient.", [33]),
(S, "Who elects the President of Pakistan?", ["An electoral college of the Senate, National Assembly and Provincial Assemblies", "Only the National Assembly", "The Supreme Court", "The Prime Minister"], 0, "Under the 1973 Constitution the President is elected by members of the Senate, the National Assembly and the four Provincial Assemblies.", "The President's term is five years.", [459]),
(S, "Who was the President of Pakistan when the 1956 Constitution was enforced?", ["Iskander Mirza", "Ghulam Muhammad", "Ayub Khan", "Yahya Khan"], 0, "Iskander Mirza became the first President of Pakistan when the 1956 Constitution came into force on 23 March 1956.", "Ayub Khan abrogated this constitution in 1958.", [92]),
(S, "In which year was interest (riba) finally prohibited in Islam, as commonly taught?", ["10 Hijri", "2 Hijri", "6 Hijri", "1 Hijri"], 0, "The final prohibition of riba came near the end of the Prophet's life and was announced in the Farewell Hajj sermon in 10 Hijri.", "Sources differ on the exact stage dates of the prohibition of riba.", [172]),
(S, "What does the Saindak Project produce?", ["Copper and gold", "Coal and iron", "Oil and gas", "Salt and gypsum"], 0, "The Saindak Project in Chagai, Balochistan produces copper, gold and some silver.", "It is run with Chinese help.", [237, 303]),
(S, "How many sajdas (places of prostration) are there in the Quran according to the Hanafi school?", ["14", "10", "15", "12"], 0, "The Quran has 14 verses of sajda according to the commonly taught view.", "The Shafi school counts 15 by including one in Surah Al-Hajj.", [224]),
(S, "Which Companion of the Prophet (SAW) has the title Jami ul Quran?", ["Hazrat Usman (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)"], 0, "Hazrat Usman (RA) is called Jami ul Quran because he had copies of the Quran made in one standard text.", "Hazrat Abu Bakr (RA) first collected the Quran in a book form.", [441]),
(S, "Between which two places was the first railway line in present Pakistan opened?", ["Karachi and Kotri", "Lahore and Amritsar", "Peshawar and Landi Kotal", "Multan and Lahore"], 0, "The first railway line in the area now Pakistan ran from Karachi to Kotri and opened in 1861.", "It was part of the Scinde Railway.", [390]),
(S, "What is the length of the Mariana Trench?", ["About 2,550 km", "About 500 km", "About 10,000 km", "About 1,000 km"], 0, "The Mariana Trench is about 2,550 km long and about 69 km wide.", "It is in the western Pacific Ocean near the Mariana Islands.", [280]),
(S, "What is the Mariana Trench?", ["The deepest part of the Earth's oceans, in the Pacific", "The longest river in Asia", "The highest plateau in the world", "A desert in Australia"], 0, "The Mariana Trench is the deepest known place in the oceans, and its deepest point is called Challenger Deep.", "Challenger Deep is about 10,900 metres deep.", [286]),
]
